<?php
$title='Bandeja de entrada'; require __DIR__.'/partials/top.php';
$pdo=appDb(); $tid=(int)$_SESSION['user']['tenant_id']; $uid=(int)$_SESSION['user']['id'];
$convs=[];$agents=[];$channels=[];$categories=[];$selected=null;$messages=[];$selectedCategories=[];$followup=null;$notes=[];
$channelFilter=$_GET['channel']??'';$assignmentFilter=$_GET['assignment']??'';$priorityFilter=$_GET['priority']??'';
try{
 if($channelFilter===''&&$assignmentFilter===''&&$priorityFilter===''){$q=$pdo->prepare('SELECT channel_type,assignment_filter,priority_filter FROM inbox_preferences WHERE user_id=?');$q->execute([$uid]);if($pr=$q->fetch()){$channelFilter=$pr['channel_type'];$assignmentFilter=$pr['assignment_filter'];$priorityFilter=$pr['priority_filter'];}}
 $channelFilter=$channelFilter?:'all';$assignmentFilter=$assignmentFilter?:'all';$priorityFilter=$priorityFilter?:'all';
 $sql="SELECT c.id,c.uuid,c.contact_id,c.assigned_user_id,c.status,c.unread_count,c.last_message_at,c.priority,c.created_at,ct.name contact_name,ct.phone,ct.email,ct.avatar_url,ch.type channel_type,ch.name channel_name,u.name agent_name,(SELECT body FROM messages m WHERE m.conversation_id=c.id ORDER BY m.sent_at DESC,m.id DESC LIMIT 1) last_body,(SELECT direction FROM messages m WHERE m.conversation_id=c.id ORDER BY m.sent_at DESC,m.id DESC LIMIT 1) last_direction FROM conversations c JOIN contacts ct ON ct.id=c.contact_id JOIN channels ch ON ch.id=c.channel_id LEFT JOIN users u ON u.id=c.assigned_user_id WHERE c.tenant_id=? AND c.status IN ('open','pending')";$params=[$tid];
 if($channelFilter!=='all'){$sql.=' AND ch.type=?';$params[]=$channelFilter;} if($assignmentFilter==='mine'){$sql.=' AND c.assigned_user_id=?';$params[]=$uid;}elseif($assignmentFilter==='unassigned')$sql.=' AND c.assigned_user_id IS NULL'; if(in_array($priorityFilter,['normal','high','urgent'],true)){$sql.=' AND c.priority=?';$params[]=$priorityFilter;} $sql.=' ORDER BY COALESCE(c.last_message_at,c.created_at) DESC';
 $q=$pdo->prepare($sql);$q->execute($params);$convs=$q->fetchAll();$cid=(int)($_GET['conversation']??($convs[0]['id']??0));foreach($convs as $c)if((int)$c['id']===$cid)$selected=$c;
 if($selected){$q=$pdo->prepare('SELECT m.*,u.name sender_name FROM messages m LEFT JOIN users u ON u.id=m.sender_user_id WHERE m.tenant_id=? AND m.conversation_id=? ORDER BY m.sent_at,m.id');$q->execute([$tid,$cid]);$messages=$q->fetchAll();}
 $q=$pdo->prepare("SELECT u.id,u.name FROM users u JOIN tenant_users tu ON tu.user_id=u.id WHERE tu.tenant_id=? AND u.status='active' ORDER BY u.name");$q->execute([$tid]);$agents=$q->fetchAll();$q=$pdo->prepare("SELECT id,name,type,status FROM channels WHERE tenant_id=? ORDER BY type,name");$q->execute([$tid]);$channels=$q->fetchAll();$q=$pdo->prepare('SELECT id,name,color FROM contact_categories WHERE tenant_id=? AND active=1 ORDER BY name');$q->execute([$tid]);$categories=$q->fetchAll();
 if($selected){$q=$pdo->prepare('SELECT category_id FROM contact_category_map WHERE contact_id=?');$q->execute([$selected['contact_id']]);$selectedCategories=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$q=$pdo->prepare("SELECT follow_up_at,note FROM conversation_followups WHERE tenant_id=? AND conversation_id=? AND status='pending' ORDER BY id DESC LIMIT 1");$q->execute([$tid,$selected['id']]);$followup=$q->fetch()?:null;$q=$pdo->prepare('SELECT cn.body,cn.created_at,u.name FROM conversation_notes cn JOIN users u ON u.id=cn.user_id WHERE cn.tenant_id=? AND cn.conversation_id=? ORDER BY cn.id DESC LIMIT 5');$q->execute([$tid,$selected['id']]);$notes=$q->fetchAll();}
}catch(Throwable $e){}
function channelMeta(string $type):array{return match($type){'whatsapp'=>['fa-brands fa-whatsapp','WhatsApp'],'messenger'=>['fa-brands fa-facebook-messenger','Messenger'],'instagram'=>['fa-brands fa-instagram','Instagram'],'webchat'=>['fa-solid fa-message','NIVO Web Chat'],default=>['fa-solid fa-comments',ucfirst($type)]};}
?>
